// CSD_RATIONALE_BEGIN
// Diagnosis of the 52% accuracy ceiling (attempt 43, the best result):
// Avg 8.61 generated tokens/example = ~5 preamble + 1 "<<" + ~1.6 SQL tokens + 1 ">>".
// The SQL grammar's IsCompletePrefix fires after only ~2 constrained tokens
// ("SELECT city FROM employee" = 4 tokens, median ~2 from the token count).
// The span closes immediately at the first complete parse point, producing
// correct-syntax but semantically incomplete SQL (missing WHERE, GROUP BY,
// HAVING, JOIN). The correct Spider answers average 15-25 SQL tokens.
//
// Fix: Add a minimum constrained token guard (|currentConstrainedOut| >= 8)
// before allowing IsCompletePrefix early-close. This forces the model to generate
// at least 8 constrained SQL tokens before the span can close, pushing past
// "SELECT col FROM table" and into WHERE/GROUP BY/JOIN territory.
//
// Structure: Identical to attempt 43 except for the minimum token guard:
// Phase 1: 5-step preamble, detect "<<" with RenderedEndsWith
// Phase 2: Force OpenConstrainedSpan if not already inside span
// Phase 3: GroupBoostedConstrainedStep + |currentConstrainedOut|>=8 guard
// Phase 4: CloseSpanWithinBudget fallback (budget 200) for unclosed spans
// Guidance: Same simple schema-grounding instruction as attempt 43 (extra hints hurt in 59)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble): Loop guard includes !insideConstrainedOut so the
//   implication is vacuous throughout. The only true-flip is RenderedEndsWith;
//   we simultaneously set currentConstrainedOut := [], and IsValidPrefix([])
//   holds by the method precondition. EOS break leaves insideConstrainedOut false.
//
// Phase 2 (OpenConstrainedSpan): Only executed when !insideConstrainedOut.
//   Postcondition: insideOut=true, currentOut=[]; IsValidPrefix([]) by precondition.
//
// Phase 3 (main loop, min-guard branch): parser.IsCompletePrefix holds (guarded),
//   so CloseConstrainedSpan's precondition is met; sets insideConstrainedOut:=false
//   (implication vacuous) and currentConstrainedOut:=[].
//   Normal GroupBoostedConstrainedStep branch: hard-masks to parser-valid tokens
//   + EOS; AppendConstrainedToken extends currentConstrainedOut by one valid token,
//   preserving IsValidPrefix by parser extension monotonicity.
//   EOS branch with close: close only called when both min-guard and IsCompletePrefix
//   hold; CloseConstrainedSpan makes implication vacuous.
//   EOS branch without close: insideConstrainedOut unchanged (was true, stays true)
//   but no append; implication preserved from previous iteration.
//
// Phase 4 (CloseSpanWithinBudget): postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep increments steps by 1 and appends ≤1 token (0 on
//   EOS, 1 on non-EOS). Preserved each iteration.
// Phase 2: OpenConstrainedSpan increments steps by 1, appends exactly 1 "<<".
//   |generated| grows by 1, steps grows by 1; 1:1 ratio preserved.
// Phase 3:
//   Close branch: CloseConstrainedSpan +1 step, appends ≤1 ">>" token. ≤1:1.
//   Normal branch: GroupBoostedConstrainedStep +1 step; AppendConstrainedToken
//   appends 1 token. Exactly 1:1 per iteration.
//   EOS+close: +1 step (EOS helper), +1 step (close), generated grows ≤1.
//   EOS+no-close: +1 step, 0 appended. Preserved.
// Phase 4: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| +
//   closeBudget; we set steps := steps + closeBudget. Preserved by transitivity.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if model didn't emit it naturally in the preamble
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control.
// KEY FIX: minimum token guard prevents premature closure at short SQL fragments.
// Without this guard, IsCompletePrefix fires at ~4 tokens ("SELECT col FROM table")
// and the span closes before WHERE/GROUP BY/JOIN can be generated.
var minConstrainedTokens: nat := 8;
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if |currentConstrainedOut| >= minConstrainedTokens && parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if |currentConstrainedOut| >= minConstrainedTokens && parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: CloseSpanWithinBudget fallback for spans still open after Phase 3
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 200 {
    closeBudget := remaining;
  } else {
    closeBudget := 200;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

